<?php
require_once dirname(__DIR__).'/includes/auth.php';$u=require_role('supervisor');$pid=filter_input(INPUT_GET,'project_id',FILTER_VALIDATE_INT)?:0;if(!project_access($pid,$u)){http_response_code(403);exit('Project is not assigned to your account.');}$q=db()->prepare('SELECT p.*,s.id session_id FROM projects p JOIN academic_sessions s ON s.id=p.academic_session_id WHERE p.id=?');$q->execute([$pid]);$project=$q->fetch();$q=db()->prepare('SELECT * FROM evaluation_criteria WHERE is_active=1 AND (academic_session_id IS NULL OR academic_session_id=?) AND (department_id IS NULL OR department_id=?) AND evaluator_role="supervisor" ORDER BY sort_order,id');$q->execute([$project['session_id'],$project['department_id']]);$criteria=$q->fetchAll();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(!$criteria)$err='No active supervisor criteria are configured for this session.';else{try{db()->beginTransaction();$comment=post_string('overall_comment',5000);db()->prepare('INSERT INTO evaluations(project_id,evaluator_id,evaluator_role,overall_comment,status) VALUES(?,?,"supervisor",?,"draft") ON DUPLICATE KEY UPDATE overall_comment=VALUES(overall_comment)')->execute([$pid,$u['id'],$comment]);$q=db()->prepare('SELECT id FROM evaluations WHERE project_id=? AND evaluator_id=?');$q->execute([$pid,$u['id']]);$eid=(int)$q->fetchColumn();$total=0.0;foreach($criteria as $c){$raw=$_POST['score'][$c['id']]??null;if(!is_scalar($raw)||!is_numeric($raw))throw new DomainException('Enter a numeric score for every criterion.');$score=(float)$raw;if($score<0||$score>(float)$c['max_score'])throw new DomainException('Scores must be within each criterion maximum.');$total+=$score*(float)$c['weight'];$note=trim((string)($_POST['criterion_comment'][$c['id']]??''));db()->prepare('INSERT INTO evaluation_scores(evaluation_id,criterion_id,score,comment) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE score=VALUES(score),comment=VALUES(comment)')->execute([$eid,$c['id'],$score,$note?:null]);}db()->prepare('UPDATE evaluations SET total_score=?,status="submitted",submitted_at=NOW() WHERE id=?')->execute([$total,$eid]);db()->commit();audit('supervisor_evaluation_submitted','evaluation',$eid,'Supervisor evaluation submitted');flash('success','Supervisor evaluation submitted.');redirect('supervisor/projects.php');}catch(DomainException $e){if(db()->inTransaction())db()->rollBack();$err=$e->getMessage();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();error_log($e->getMessage());$err='Evaluation could not be saved.';}}}$pageTitle='Supervisor Evaluations';$crumbTrail=['Evaluations'];require dirname(__DIR__).'/includes/header.php';
?><h2 class="h5"><?= e($project['title']) ?></h2><?php if($err): ?><div role="alert" class="alert alert-danger"><?= e($err) ?></div><?php endif; ?><?php if(!$criteria): ?><div class="alert alert-info">No supervisor evaluation criteria are configured.</div><?php else: ?><form method="post" class="card p-4"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><?php foreach($criteria as $c): ?><div class="row align-items-end border-bottom py-3"><div class="col-md-6"><label class="form-label fw-semibold"><?= e($c['name']) ?> (max <?= e((string)$c['max_score']) ?>)</label><div class="small text-muted"><?= e($c['description']??'') ?></div></div><div class="col-md-2"><input class="form-control" type="number" name="score[<?= (int)$c['id'] ?>]" min="0" max="<?= e((string)$c['max_score']) ?>" step="0.01" required></div><div class="col-md-4"><input class="form-control" name="criterion_comment[<?= (int)$c['id'] ?>]" placeholder="Optional criterion comment"></div></div><?php endforeach; ?><label class="form-label mt-3">Overall comments</label><textarea class="form-control" name="overall_comment" rows="4"></textarea><button class="btn btn-primary mt-3">Submit supervisor evaluation</button></form><?php endif; ?><?php require dirname(__DIR__).'/includes/footer.php'; ?>
